/**
 * Equivalent of assertBoardOrgAccess for RequestCtx.
 * Requires board actor; company-list membership is enforced by the upstream
 * Express auth middleware for authenticated deployments.
 * TODO(cloudflare): re-enforce org-level membership in Workers auth layer.
 */
function assertBoardOrgAccessCtx(ctx: RequestCtx) {
  if (ctx.actor?.type !== "board") {
    throw forbidden("Board access required");
  }
}

/**
 * Requires board actor with instance-admin privileges.
 * ctx.actor lacks `source` and `isInstanceAdmin`; we cannot check those fields
 * here. The upstream Express auth middleware populates req.actor.isInstanceAdmin
 * which is not forwarded to ActorContext.
 * TODO(cloudflare): add isInstanceAdmin / source to ActorContext for Workers.
 */
function assertCanManageInstanceSettingsCtx(ctx: RequestCtx) {
  if (ctx.actor?.type !== "board") {
    throw forbidden("Board access required");
  }
  // In the Express path, local_implicit and isInstanceAdmin actors pass through
  // without further DB checks. Under Workers that information is unavailable on
  // ActorContext, so we cannot replicate the fast-path; callers in Workers will
  // reach the instance admin check below only after auth middleware re-surfaces
  // the privilege.
  // TODO(cloudflare): verify instance-admin gate in Workers auth layer.
